sys.path.insert(0,str(Path(__file__).resolve().parents[1]));sys.path.insert(0,str(Path(__file__).resolve().parent))
from gongbi_training.runtime import configure,LAB
configure()
import torch,numpy as np
from PIL import Image,ImageDraw,ImageFont
from guohua_scene4_20261116 import ROOT,OLD,NEW,ARMS,read,write,sha
from gongbi_training.scene_object_reference import legacy_object_to_scene,sparse_scene_reference
from gongbi_training.scene_objects import scene_metrics
ALL=['legacy']+ARMS;NAMES=['旧三类模型','四类基础组','四类＋线描参考'];COLORS=np.array([[232,235,225],[183,134,75],[65,149,91],[145,157,170]],'uint8')
def main():
 res=read(ROOT/'results.json');p=res['protocol'];refs=read(ROOT/'references.json');ds=read(ROOT/'dataset_manifest.json');assert sha(ROOT/'references.json')==p['reference_sha256'];assert sha(ROOT/'dataset_manifest.json')==p['dataset_sha256'];assert sha(Path(__file__).with_name('guohua_scene4_20261116.py'))==p['script_sha256'];assert sha(Path(__file__).resolve().parents[1]/'gongbi_training/scene_objects.py')==p['scene_module_sha256'];assert sha(OLD/'results.json')==p['old_results_sha256'];assert sha(OLD/'expanded_control.pt')==p['initial_sha256'];assert sha(NEW/'references.json')==p['new_photo_reference_sha256'];(ROOT/'views').mkdir(exist_ok=True)
 oldstate=torch.load(OLD/'expanded_control.pt',map_location='cpu',weights_only=False)['model']
 for a,h in res['checkpoint_hashes'].items():
  assert sha(ROOT/(a+'.pt'))==h;state=torch.load(ROOT/(a+'.pt'),map_location='cpu',weights_only=False)['model'];assert all(torch.equal(v,state[k]) for k,v in oldstate.items() if k.startswith('encoder.'))
 byid={r['id']:r for r in ds['records']};manual={c['id']:c for c in refs['photo_cases']+refs['video_cases']};records=[];local=[]
 for r in res['records']:
  if r['split']=='validation_named':continue
  ident=r['id'];im=Image.open(r['image']).convert('RGB');im.save(ROOT/'views'/(ident+'_input.png'));paths={}
  if ident in manual:target,_=sparse_scene_reference(manual[ident]['size'],manual[ident]['regions'])
  elif ident in byid:target=legacy_object_to_scene(np.array(Image.open(byid[ident]['target'])))
  else:target=None
  for a in ALL:
   pred=np.load(ROOT/'predictions'/(ident+'_'+a+'.npz'))['prediction'];Image.fromarray(COLORS[pred]).save(ROOT/'views'/(ident+'_'+a+'.png'));paths[a]='views/'+ident+'_'+a+'.png'
   if target is not None:assert scene_metrics(target,pred)['confusion']==r['scores'][a]['confusion']
  records.append(dict(id=ident,split=r['split'],work_group=r['work_group'],input='views/'+ident+'_input.png',predictions=paths))
 # Diagnostics use sparse assistant cores only; keep in-sample, development holdout,
 # and known user case categories visible instead of aggregating them together.
 oldh=read(LAB/'guohua_boundary_reference_20261116/reviewed_references.json');hcase=next(c for c in oldh['cases'] if c['id']=='H_14')
 for c in list(manual.values())+[hcase]:
  ident=c['id'];regions=[]
  for r in c['regions']:
   if r['kind']!='core_polygon' or r['object']=='unknown':continue
   targetid={'open_scene':0,'rock':1,'tree':2,'other_object':3}[r['object']];mask=Image.new('L',tuple(c['size']),0);ImageDraw.Draw(mask).polygon([tuple(v) for v in r['points']],fill=255);m=np.array(mask)>0
   regions.append(dict(name=r['name'],object=r['object'],scores={a:float((np.load(ROOT/'predictions'/(ident+'_'+a+'.npz'))['prediction'][m]==targetid).mean()) for a in ALL}))
  local.append(dict(id=ident,split=next(r['split'] for r in records if r['id']==ident),regions=regions))
 write('report_data.json',dict(records=records,aggregates=res['aggregates'],user=res['user_foliage_recall'],local=local))
 def board(rows,name):
  b=Image.new('RGB',(1440,len(rows)*350+65),'#f4f1e8');d=ImageDraw.Draw(b);font=ImageFont.truetype('C:/Windows/Fonts/msyh.ttc',18)
  for i,r in enumerate(rows):
   for j,(path,title) in enumerate(zip([r['input']]+[r['predictions'][a] for a in ALL],['原图']+NAMES)):
    im=Image.open(ROOT/path);im.thumbnail((346,280));b.paste(im,(j*360+6,i*350+35));d.text((j*360+6,i*350+5),title,font=font,fill='#294735')
   d.text((6,i*350+320),r['id']+' / '+r['split'],font=font,fill='#79523a')
  d.text((6,len(rows)*350+4),'浅灰绿=新增空景，棕=山石，绿=树木，灰蓝=其他；对象区域不是墨带或完整笔触。',font=font,fill='#79523a');b.save(ROOT/name,quality=94)
 board(records[:1],'foliage_regression.jpg');board([r for r in records if r['split']=='photo_holdout'],'work_holdout.jpg');board([r for r in records if r['split']=='train_video'],'video_fit.jpg')
 selection=read(NEW/'selection_before_download.json');reserved={Path(x).stem for x in selection['reserved_paths']};assert not any(p.stem in reserved for p in (NEW/'raw').glob('*.jpg'));assert not ({c['work_group'] for c in refs['photo_cases'] if c['split']=='train_photo'}&{c['work_group'] for c in refs['photo_cases'] if c['split']=='photo_holdout'})
 checks=read(ROOT/'pretrain_checks.json');checks.update(hashes_match=True,old_artifacts_unchanged=True,encoders_unchanged_after_training=True,raw_confusions_recomputed=True,holdout_work_not_training=True,reserved_still_metadata_only=True,model_adopted=False,expert_accuracy=False,independent_acceptance=False,robot_connected=False);write('verification.json',checks)
 page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>空景与线描山体：四类候选对照</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f1e8;color:#294735;font:16px/1.7 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1500px;margin:auto;padding:24px}h1{font-size:29px}.note{padding:15px;background:#fff8e8;border-left:5px solid #b67c44}.warn{color:#875139}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.card{min-width:0;background:#fffdf8;border:1px solid #d1d6c8;padding:10px}img{max-width:100%;height:auto;display:block;margin:auto}select{width:650px;max-width:100%;font:inherit;padding:8px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}td,th{padding:9px;border-bottom:1px solid #d1d6c9;text-align:left}a{color:#236b61}@media(max-width:700px){main{padding:14px}.grid{grid-template-columns:1fr}h1{font-size:24px}}</style><main><small>2026-11-16 · 四类独立候选 · 未替换绘画版本</small><h1>新增空景类别，单独检查真实线描参考的作用</h1><p class="note" id="headline"></p><p>两组都从旧三类权重迁移：旧其他0→新其他3，山石1、树木2不变，空景0新增。冻结编码器，各256步、相同图片/增强/预算；两组均使用旧63张粗对象训练图、4张新画作的稀疏场景参考，只有一组额外监督4个真实教程帧中的11处明确内部区域。它们是两个示范作品的帧，不是4件独立作品。不是用合成线条替代真实线描。</p><p>一帧被毛笔遮住的岩面在训练前已改为未知，原标记与协议保留。对象参考仍由助手选择，非专家真值或墨迹分笔。场景和可见墨迹保持独立，未将留白对象内部自动标成背景。</p><h2>1. 已知用户案例：树叶与留白山体</h2><img src="foliage_regression.jpg"><p id="foliage"></p><p>H_14仍未进入训练，是已反复查看的案例；召回使用旧1,647像素树叶核心，非叶片精确边界。另列更小的对象参考，分母不同。不能只凭这个案例认定泛化。</p><h2>2. 整组新作品的开发留出</h2><img src="work_holdout.jpg"><p>文件名zhao-ji_autumn-colors两张参考图属于同一完整作品候选组，未进入任一对象训练。该作品已预览和标过参考，是开发留出，不能称新盲测或专家验收；文件名作者和原作归属未独立认证。</p><div class="scroll"><table><thead><tr><th>开发留出</th><th>空景参考召回</th><th>山石参考召回</th><th>树木参考召回</th></tr></thead><tbody id="holdout"></tbody></table></div><p>上述只针对助手稀疏区域；旧三类没有空景类别，此列标“无此类别”，不能拿其必为0的结果宣传提升。需比较两个四类候选，且不能从该小样推断所有淡山体。</p><h2>3. 旧作品回归：保持可比口径</h2><div class="scroll"><table><thead><tr><th>范围</th><th>方法</th><th>原三种前景平均IoU</th><th>山石IoU</th><th>树木IoU</th></tr></thead><tbody id="metrics"></tbody></table></div><p class="warn">旧14图、12图均是已知回归。源标注没有空景真值，故这里只比较山石、树木、其他三种前景IoU；新增空景的错误预测仍会造成前景漏检，未忽略它们。没有混用三类/四类平均数。所有指标不是皴法辨识或完整笔画恢复率。</p><h2>4. 逐张查看直接输出</h2><select id="case"></select><p id="scope"></p><div class="grid"><div class="card"><b>原图</b><img id="input"></div><div class="card"><b>旧三类模型</b><img id="legacy"></div><div class="card"><b>四类基础组</b><img id="scene_base"></div><div class="card"><b>四类＋线描参考</b><img id="scene_plus_line"></div></div><p id="refnote">稀疏参考，无完整对象边界。浅灰绿=新增空景，棕=山石，绿=树木，灰蓝=其他对象。预测未经参考蒙版修饰，色块不是线稿、墨带或皴法效果。</p><h2>5. 各处参考的诊断</h2><div class="scroll"><table><thead><tr><th>图像／用途</th><th>对象内部参考</th><th>旧三类</th><th>四类基础</th><th>四类＋线描</th></tr></thead><tbody id="local"></tbody></table></div><p>train_photo、train_video为样本内拟合，不能作泛化证据；photo_holdout是开发作品留出；H_14是已知错例。未监督待定区、未使用轮廓走廊作为真值。没有据结果挑轮次、阈值或加训。</p><details><summary>展开真实教程训练帧的拟合情况</summary><img src="video_fit.jpg"></details><h2>6. 仍保留的阶段约束</h2><p>两个其他作品候选组47条路径仍仅保留元数据，未下载、预览或预测。对象与皴法未通过独立验收，树木画法训练保持关闭，未连接机械臂。本轮建立并验证四类接口候选，不等于学会皴法或完整笔触。下一步由跨作品、树石交界与纯线描失败决定补哪些参考，不能只看训练帧变好。</p><p><a href="protocol.json">冻结协议</a> · <a href="references.json">参考、用途与来源</a> · <a href="references_pre_visual_review.json">训练前修订的原始参考</a> · <a href="results.json">全部结果</a> · <a href="verification.json">验证记录</a></p></main><script>let D;const A=['legacy','scene_base','scene_plus_line'],N=['旧三类','四类基础','四类＋线描'],$=s=>document.getElementById(s),pct=x=>x===null?'无参考':(x*100).toFixed(1)+'%';function show(){let r=D.records[$('case').selectedIndex];$('input').src=r.input;for(let a of A)$(a).src=r.predictions[a];$('scope').textContent=r.id+' / '+r.split+' / '+r.work_group}fetch('report_data.json').then(r=>r.json()).then(d=>{D=d;for(let r of d.records){let o=document.createElement('option');o.textContent=r.id;$('case').append(o)}$('case').onchange=show;show();let q=d.aggregates.new_test;$('headline').textContent='已知14图原三类前景平均IoU：'+A.map((a,i)=>N[i]+' '+pct(q[a].known_foreground_mean_iou)).join('；')+'。须同时检查空景误吞山体、树叶和开发留出。没有自动替换旧版。';$('foliage').textContent='原有树叶核心召回：'+A.map((a,i)=>N[i]+' '+pct(d.user[a])).join('；');for(let [i,a] of A.entries()){let v=d.aggregates.photo_holdout[a],tr=document.createElement('tr');tr.innerHTML='<td>'+N[i]+'</td>'+[a==='legacy'?'无此类别':pct(v.recall[0]),pct(v.recall[1]),pct(v.recall[2])].map(x=>'<td>'+x+'</td>').join('');$('holdout').append(tr)}for(let [s,t] of [['new_test','已知14图'],['old_named_regression','旧12图／1作品组']])for(let [i,a] of A.entries()){let v=d.aggregates[s][a],tr=document.createElement('tr');tr.innerHTML='<td>'+t+'</td><td>'+N[i]+'</td>'+[v.known_foreground_mean_iou,v.iou[1],v.iou[2]].map(x=>'<td>'+pct(x)+'</td>').join('');$('metrics').append(tr)}for(let c of d.local)for(let r of c.regions){let tr=document.createElement('tr');tr.innerHTML='<td>'+c.id+' / '+c.split+'</td><td>'+r.name+' / '+r.object+'</td>'+A.map(a=>'<td>'+((a==='legacy'&&r.object==='open_scene')?'无此类别':pct(r.scores[a]))+'</td>').join('');$('local').append(tr)}window.reportReady=true});</script></html>'''
 page=page.replace('<h1>新增空景类别，单独检查真实线描参考的作用</h1>','<h1>四类候选已训练：示范拟合改善，空景跨作品仍失败</h1><p class="note"><b>本轮不采用新候选。</b>加入线描参考后，训练示范所选区域拟合达100%，但这只是样本内结果。留出作品所选空景召回仅约0.1%，淡山体参考召回78.7%，低于旧模型83.3%。已知14图前景平均IoU：旧版70.6%、四类基础69.6%、四类＋线描69.2%。H_14树叶核心恢复到100%，不能抵消跨作品失败。</p>')
 page=page.replace('<h2>2. 整组新作品的开发留出</h2>','<p class="note">已知H_14确有局部变化：两处预先选定的留白山面，旧模型对象对应比例16.7%／39.7%，线描参考组均为100%；同一张图前景岩面参考则从100%降至88.8%。这些是助手选定的稀疏对象区域，非完整边界、墨迹或独立验收，不能只展示变好的两处。</p><h2>2. 整组新作品的开发留出</h2>')
 (ROOT/'index.html').write_text(page,encoding='utf8')
 source=Path(__file__).with_name('serve_guohua_objects_v2_20261113.py').read_text('utf8').replace('guohua_objects_v2_20261113','guohua_scene4_20261116');a=source.index('ALLOWED={');b=source.index('\nALLOWED.update',a);source=source[:a]+"ALLOWED={'index.html','foliage_regression.jpg','work_holdout.jpg','video_fit.jpg','report_data.json','protocol.json','references.json','references_pre_visual_review.json','results.json','verification.json'}"+source[b:];(ROOT/'serve_report.py').write_text(source.replace('str(Path(__file__).resolve().parents[1])',repr(str(Path(__file__).resolve().parents[1]))),encoding='utf8')
 checker=Path(__file__).with_name('check_guohua_objects_v2_view_20261113.py').read_text('utf8').replace('guohua_objects_v2_20261113','guohua_scene4_20261116').replace(')==27',')==37').replace('range(27)','range(37)').replace(';assert js("document.querySelectorAll(\'#works tr\').length")==4','').replace('work_metrics_four_rows=True,','').replace('all27_observations_switch_and_load','all37_observations_switch_and_load').replace("['protocol.json','results.json','selection_before_download.json','source_checked_cunfa_concepts.json','verification.json']","['protocol.json','results.json','references.json','verification.json']").replace("'expanded_control.pt','line_aware_aug.pt','../expanded_control.pt','predictions/H_14_expanded_control.npz'","'scene_base.pt','scene_plus_line.pt','../scene_plus_line.pt','predictions/H_14_scene_plus_line.npz'")
 checker=checker.replace("assert requests.post(url,timeout=5).status_code==405","assert js('document.querySelectorAll(\"#holdout tr\").length')==3\n assert js('document.querySelectorAll(\"#local tr\").length')==35\n assert requests.post(url,timeout=5).status_code==405")
 (ROOT/'check_report.py').write_text(checker.replace('str(Path(__file__).resolve().parents[1])',repr(str(Path(__file__).resolve().parents[1]))),encoding='utf8');print(json.dumps(checks),flush=True)
if __name__=='__main__':main()
